127	/// Flag that can only be set once.
128	#[derive(Debug, Clone)]
129	pub(crate) struct OnceFlag(Rc<Cell<bool>>);
130	
131	impl OnceFlag {
132	    /// Creates a new `OnceFlag`.
133	    pub(crate) fn new() -> Self {
134	        Self(Rc::new(Cell::new(false)))
135	    }
136	
137	    /// Sets this `OnceFlag` to `true`.
138	    pub(crate) fn set(&self) {
139	        self.0.set(true);
140	    }
141	
142	    /// Returns `true` if this `OnceFlag` has been set, or `false` otherwise.
143	    pub(crate) fn is_set(&self) -> bool {
144	        self.0.get()
145	    }
146	}
