148	/// An ECMAScript [Job] that runs after a certain amount of time.
149	///
150	/// This represents the [HostEnqueueTimeoutJob] operation from the specification.
151	///
152	/// [HostEnqueueTimeoutJob]: https://tc39.es/ecma262/#sec-hostenqueuetimeoutjob
153	#[derive(Debug)]
154	pub struct TimeoutJob {
155	    /// The distance in milliseconds in the future when the job should run.
156	    /// This will be added to the current time when the job is enqueued.
157	    timeout: JsDuration,
158	    /// The job to run after the time has passed.
159	    job: NativeJob,
160	    /// Signals if the timeout job was cancelled.
161	    cancelled: OnceFlag,
162	    /// Signals that this job is recurring. A recurring job shouldn't be
163	    /// awaited for when considering whether a run of the event loop is
164	    /// done.
165	    recurring: bool,
166	}
167	
168	impl TimeoutJob {
169	    /// Create a new `TimeoutJob` with a timeout and a job.
170	    #[must_use]
171	    pub fn new(job: NativeJob, timeout_in_millis: u64) -> Self {
172	        Self {
173	            timeout: JsDuration::from_millis(timeout_in_millis),
174	            job,
175	            cancelled: OnceFlag::new(),
176	            recurring: false,
177	        }
178	    }
179	
180	    /// Create a new `TimeoutJob` that is marked as recurring.
181	    #[must_use]
182	    pub fn recurring(job: NativeJob, timeout_in_millis: u64) -> Self {
183	        Self {
184	            timeout: JsDuration::from_millis(timeout_in_millis),
185	            job,
186	            cancelled: OnceFlag::new(),
187	            recurring: true,
188	        }
189	    }
