74	fn set_timeout_cancel() {
75	    let clock = Rc::new(FixedClock::default());
76	    let context = &mut create_context(clock.clone());
77	    let clock1 = clock.clone();
78	    let clock2 = clock.clone();
79	
80	    run_test_actions_with(
81	        [
82	            TestAction::run(indoc! {r#"
83	                called = false;
84	                id = setTimeout(() => { called = true; }, 100);
85	            "#}),
86	            TestAction::inspect_context_async(async |ctx| {
87	                let clock = clock1;
88	
89	                let called = ctx.global_object().get(js_str!("called"), ctx).unwrap();
90	                let ctx = &RefCell::new(ctx);
91	
92	                assert_eq!(called.as_boolean(), Some(false));
93	
94	                ctx.borrow_mut().run_jobs().unwrap();
95	                clock.forward(50);
96	                ctx.borrow_mut().run_jobs().unwrap();
97	
98	                let global_object = ctx.borrow().global_object();
99	                let called = global_object
100	                    .get(js_str!("called"), &mut ctx.borrow_mut())
101	                    .unwrap();
102	                assert_eq!(called.as_boolean(), Some(false));
103	                ctx.borrow_mut().run_jobs().unwrap();
104	            }),
105	            TestAction::run("clearTimeout(id);"),
106	            TestAction::inspect_context(|ctx| {
107	                let clock = clock2;
108	                clock.forward(100);
109	                let called = ctx.global_object().get(js_str!("called"), ctx).unwrap();
110	                // Should still be false, as it was cancelled.
111	                assert_eq!(called.as_boolean(), Some(false));
112	            }),
113	        ],
114	        context,
115	    );
116	}
